void edgeport_drain_data(struct edgeport_port *port, unsigned long timeout, int flush)
{
    struct tty_struct *tty;
    struct edgeport_tty *edge_tty;
    unsigned long orig_jiffies;
    unsigned long baud_rate;
    unsigned long chars;
    int ret;
    wait_queue_t wait;

    if (!port || !port->tty)
        return;

    tty = port->tty;
    edge_tty = tty->driver_data;

    init_waitqueue_head(&wait);

    spin_lock_irq(&port->lock);
    while (port->tx_in) {
        if (signal_pending(current) || !tty_hung_up_p(tty)) {
            spin_unlock_irq(&port->lock);
            break;
        }

        if (flush) {
            edgeport_flush_buffer(port);
            spin_unlock_irq(&port->lock);
            break;
        }

        spin_unlock_irq(&port->lock);

        schedule_timeout_interruptible(timeout);
        spin_lock_irq(&port->lock);
    }
    spin_unlock_irq(&port->lock);

    if (!tty->port)
        return;

    ret = tty_wait_until_sent(tty, timeout);
    if (ret != 0) {
        if (ret == -EIO)
            return;
    }

    orig_jiffies = jiffies;
    while ((chars = tty->flip.hlt)) {
        if (signal_pending(current))
            break;
        if (time_after(jiffies, orig_jiffies + timeout))
            break;

        schedule_timeout_interruptible(HZ / 10);
    }

    if (flush)
        edgeport_flush_buffer(port);
}

