void edgeport_drain(struct edgeport_port *port, unsigned long timeout, int flush)
{
	struct tty_struct *tty;
	DECLARE_WAITQUEUE(wait, current);
	unsigned long jiffies_timeout;
	int draining = 1;
	int disconn;

	tty = port->port.tty;
	if (!tty)
		return;

	add_wait_queue(&port->wait, &wait);
	jiffies_timeout = jiffies + timeout;

	while (draining) {
		disconn = port->disconnected;
		if (disconn)
			break;

		if (time_after(jiffies, jiffies_timeout))
			break;

		if (port->port.x_char)
			continue;

		if (port->port.flags & ASYNC_BROKEN_MUX)
			continue;

		if (port->port.irq_count && time_before(jiffies, jiffies_timeout))
			continue;

		if (port->port.irq_count && port->port.icount.parity)
			continue;

		draining = 0;
	}

	remove_wait_queue(&port->wait, &wait);
	wake_up(&port->wait);

	if (flush)
		port->port.flags |= ASYNC_BROKEN_MUX;

	if (!disconn)
		wait_for_xmitr(tty, jiffies_timeout);
}

void edgeport_drain_data(struct edgeport_port *port, unsigned long timeout, int flush)
{
    struct tty_struct *tty;
    wait_queue_t wait;
    unsigned long orig_jiffies;
    int discon;
    int ret;

    if (!port || !port->port)
        return;

    tty = port->port;
    if (!tty || !tty_port_initialized(&tty->port))
        return;

    init_waitqueue_head(&wait);

    spin_lock_irq(&port->port_lock);

    if (flush) {
        discon = port->disconnected;
        if (!discon) {
            port->disconnected = 1;
            spin_unlock_irq(&port->port_lock);

            ret = tty_hangup(tty);
            if (ret)
                return;

            spin_lock_irq(&port->port_lock);
        }
    }

    orig_jiffies = jiffies;
    while ((port->tx_remaining > 0) && (port->disconnected == 0)) {
        if (signal_pending(current))
            break;

        if (time_after(jiffies, orig_jiffies + timeout))
            break;

        if (wait_event_interruptible_timeout(wait, (port->tx_remaining == 0 || port->disconnected != 0), timeout))
            break;

        schedule();
    }

    spin_unlock_irq(&port->port_lock);

    if (!flush)
        return;

    port->disconnected = 1;

    if (!tty_hung_up_p(tty))
        tty_hangup(tty);
}

void edgeport_drain_data(struct edgeport_port *port, unsigned long timeout, int flush)
{
	struct tty_struct *tty = port->tty;
	unsigned long orig_jiffies = jiffies;
	unsigned long chars;
	DECLARE_WAITQUEUE(wait, current);
	int disconn;

	if (!tty)
		return;

	add_wait_queue(&tty->write_wait, &wait);
	while (1) {
		set_current_state(TASK_INTERRUPTIBLE);
		disconn = port->disconnected;
		if (disconn || time_after(jiffies, orig_jiffies + timeout))
			break;
		chars = tty_chars_in_buffer(tty);
		if (!chars)
			break;
		if (signal_pending(current)) {
			disconn = 1;
			break;
		}
		spin_unlock_irq(&port->lock);
		schedule_timeout(1);
		spin_lock_irq(&port->lock);
	}
	set_current_state(TASK_RUNNING);
	remove_wait_queue(&tty->write_wait, &wait);

	if (flush)
		tty->driver->flush_chars(tty);

	/* Wait for the transmit buffer to drain */
	chars = tty_chars_in_buffer(tty);
	if (chars) {
		int divisor;
		unsigned long limit;

		divisor = port->baud_rate ? port->baud_rate / 1000 : 19200 / 1000;
		limit = (chars * divisor + 999) / 1000;
		msleep_interruptible(limit);
	}
}
